ad, '$.longestStreak') AS REAL))<=1000000000000 AND CAST(json_extract(s.payload, '$.longestStreak') AS REAL)=CAST(json_extract(s.payload, '$.longestStreak') AS INTEGER) AND CAST(json_extract(s.payload, '$.longestStreak') AS REAL) BETWEEN 0 AND 2147483647)) THEN CAST(json_extract(s.payload, '$.longestStreak') AS INTEGER) END,CASE WHEN json_type(s.payload, '$.lastCompletedDate') IN ('text','null') THEN json_extract(s.payload, '$.lastCompletedDate') END,(SELECT json_group_array(p.key) FROM json_each(s.payload) p WHERE (p.key='id' AND (json_type(s.payload, '$.id') IN ('text','null') OR (json_type(s.payload, '$.id') IN ('integer','real') AND abs(json_extract(s.payload, '$.id'))<=1.7976931348623157e308))) OR (p.key='createdAt' AND json_type(s.payload, '$.createdAt') IN ('text','null')) OR (p.key='updatedAt' AND json_type(s.payload, '$.updatedAt') IN ('text','null')) OR (p.key='streak' AND (json_type(s.payload, '$.streak')='null' OR ((json_type(s.payload, '$.streak') IN ('integer','real') OR (json_type(s.payload, '$.streak')='text' AND CASE WHEN json_valid(json_extract(s.payload, '$.streak')) THEN json_type(json_extract(s.payload, '$.streak')) IN ('integer','real') ELSE false END)) AND abs(CAST(json_extract(s.payload, '$.streak') AS REAL))<=1000000000000 AND CAST(json_extract(s.payload, '$.streak') AS REAL)=CAST(json_extract(s.payload, '$.streak') AS INTEGER) AND CAST(json_extract(s.payload, '$.streak') AS REAL) BETWEEN 0 AND 2147483647))) OR (p.key='longestStreak' AND (json_type(s.payload, '$.longestStreak')='null' OR ((json_type(s.payload, '$.longestStreak') IN ('integer','real') OR (json_type(s.payload, '$.longestStreak')='text' AND CASE WHEN json_valid(json_extract(s.payload, '$.longestStreak')) THEN json_type(json_extract(s.payload, '$.longestStreak')) IN ('integer','real') ELSE false END)) AND abs(CAST(json_extract(s.payload, '$.longestStreak') AS REAL))<=1000000000000 AND CAST(json_extract(s.payload, '$.longestStreak') AS REAL)=CAST(json_extract(s.payload, '$.longestStreak') AS INTEGER) AND CAST(json_extract(s.payload, '$.longestStreak') AS REAL) BETWEEN 0 AND 2147483647))) OR (p.key='lastCompletedDate' AND json_type(s.payload, '$.lastCompletedDate') IN ('text','null')) OR (p.key='schedule' AND ((json_type(s.payload, '$.schedule')='array' AND json_array_length(CASE WHEN json_type(s.payload, '$.schedule')='array' THEN json_extract(s.payload, '$.schedule') ELSE '[]' END)<=1000 AND NOT EXISTS(SELECT 1 FROM json_each(CASE WHEN json_type(s.payload, '$.schedule')='array' THEN json_extract(s.payload, '$.schedule') ELSE '[]' END) item WHERE item.type<>'object')) OR json_type(s.payload, '$.schedule')='null')) OR (p.key='prHistory' AND ((json_type(s.payload, '$.prHistory')='array' AND json_array_length(CASE WHEN json_type(s.payload, '$.prHistory')='array' THEN json_extract(s.payload, '$.prHistory') ELSE '[]' END)<=1000 AND NOT EXISTS(SELECT 1 FROM json_each(CASE WHEN json_type(s.payload, '$.prHistory')='array' THEN json_extract(s.payload, '$.prHistory') ELSE '[]' END) item WHERE item.type<>'object')) OR json_type(s.payload, '$.prHistory')='null')) OR (p.key='PRs' AND json_type(s.payload, '$.PRs') IN ('object','null'))),NULLIF((SELECT json_group_object(p.key,json(CASE WHEN p.key='PRs' AND json_type(s.payload, '$.PRs')='object' THEN (SELECT json_group_object(entry.key,json(CASE entry.type WHEN 'text' THEN json_quote(entry.value) WHEN 'true' THEN 'true' WHEN 'false' THEN 'false' WHEN 'null' THEN 'null' ELSE entry.value END)) FROM json_each(CASE WHEN json_type(s.payload, '$.PRs')='object' THEN json_extract(s.payload, '$.PRs') ELSE '{}' END) entry WHERE NOT (entry.type='null' OR ((entry.type IN ('integer','real') OR (entry.type='text' AND CASE WHEN json_valid(entry.value) THEN json_type(entry.value) IN ('integer','real') ELSE false END)) AND abs(CAST(entry.value AS REAL))<=1000000000000))) ELSE CASE p.type WHEN 'text' THEN json_quote(p.value) WHEN 'true' THEN 'true' WHEN 'false' THEN 'false' WHEN 'null' THEN 'null' ELSE p.value END END)) FRO