INSERT INTO "training_personal_records" (id,parentId,scope,key,valueType,value,stringValue,booleanValue,unit)
SELECT s.id||':PRs:'||hex(j.key),s.id,'PRs',j.key,
 CASE j.type WHEN 'null' THEN 'null' ELSE 'number' END,
 CASE WHEN j.type<>'null' THEN CAST(j.value AS REAL) END,
 NULL,NULL,'kg'
 FROM "_plan_source_TrainingPlan" s,json_each(CASE WHEN json_type(s.payload, '$.PRs')='object' THEN json_extract(s.payload, '$.PRs') ELSE '{}' END) j WHERE (j.type='null' OR ((j.type IN ('integer','real') OR (j.type='text' AND CASE WHEN json_valid(j.value) THEN json_type(j.value) IN ('integer','real') ELSE false END)) AND abs(CAST(j.value AS REAL))<=1000000000000));

