on_type(s.payload, '$.exercises')='array' THEN json_extract(s.payload, '$.exercises') ELSE '[]' END) item WHERE item.type<>'object')) OR json_type(s.payload, '$.exercises')='null'))),NULLIF((SELECT json_group_object(p.key,json(CASE p.type WHEN 'text' THEN json_quote(p.value) WHEN 'true' THEN 'true' WHEN 'false' THEN 'false' WHEN 'null' THEN 'null' ELSE p.value END)) FROM json_each(s.payload) p WHERE NOT ((p.key='id' AND (json_type(s.payload, '$.id') IN ('text','null') OR (json_type(s.payload, '$.id') IN ('integer','real') AND abs(json_extract(s.payload, '$.id'))<=1.7976931348623157e308))) OR (p.key='createdAt' AND json_type(s.payload, '$.createdAt') IN ('text','null')) OR (p.key='updatedAt' AND json_type(s.payload, '$.updatedAt') IN ('text','null')) OR (p.key='day' AND json_type(s.payload, '$.day') IN ('text','null')) OR (p.key='muscleGroup' AND json_type(s.payload, '$.muscleGroup') IN ('text','null')) OR (p.key='exercises' AND (json_type(s.payload, '$.exercises')='array' AND json_array_length(CASE WHEN json_type(s.payload, '$.exercises')='array' THEN json_extract(s.payload, '$.exercises') ELSE '[]' END)<=1000 AND NOT EXISTS(SELECT 1 FROM json_each(CASE WHEN json_type(s.payload, '$.exercises')='array' THEN json_extract(s.payload, '$.exercises') ELSE '[]' END) item WHERE item.type<>'object'))))),'{}') FROM "_plan_source_TrainingDay" s;

