 NOT (entry.type IN ('text','true','false','null') OR (entry.type IN ('integer','real') AND abs(entry.value)<=1.7976931348623157e308))) WHEN p.key='privateMetrics' AND json_type(s.payload, '$.privateMetrics')='object' THEN (SELECT json_group_object(entry.key,json(CASE entry.type WHEN 'text' THEN json_quote(entry.value) WHEN 'true' THEN 'true' WHEN 'false' THEN 'false' WHEN 'null' THEN 'null' ELSE entry.value END)) FROM json_each(CASE WHEN json_type(s.payload, '$.privateMetrics')='object' THEN json_extract(s.payload, '$.privateMetrics') ELSE '{}' END) entry WHERE NOT (entry.type IN ('text','true','false','null') OR (entry.type IN ('integer','real') AND abs(entry.value)<=1.7976931348623157e308))) ELSE CASE p.type WHEN 'text' THEN json_quote(p.value) WHEN 'true' THEN 'true' WHEN 'false' THEN 'false' WHEN 'null' THEN 'null' ELSE p.value END END)) FROM json_each(s.payload) p WHERE NOT ((p.key='id' AND (json_type(s.payload, '$.id') IN ('text','null') OR (json_type(s.payload, '$.id') IN ('integer','real') AND abs(json_extract(s.payload, '$.id'))<=1.7976931348623157e308))) OR (p.key='createdAt' AND json_type(s.payload, '$.createdAt') IN ('text','null')) OR (p.key='updatedAt' AND json_type(s.payload, '$.updatedAt') IN ('text','null')) OR (p.key='targets' AND (json_type(s.payload, '$.targets')='array' AND json_array_length(CASE WHEN json_type(s.payload, '$.targets')='array' THEN json_extract(s.payload, '$.targets') ELSE '[]' END)<=1000 AND NOT EXISTS(SELECT 1 FROM json_each(CASE WHEN json_type(s.payload, '$.targets')='array' THEN json_extract(s.payload, '$.targets') ELSE '[]' END) item WHERE item.type<>'object'))) OR (p.key='milestones' AND (json_type(s.payload, '$.milestones')='array' AND json_array_length(CASE WHEN json_type(s.payload, '$.milestones')='array' THEN json_extract(s.payload, '$.milestones') ELSE '[]' END)<=1000 AND NOT EXISTS(SELECT 1 FROM json_each(CASE WHEN json_type(s.payload, '$.milestones')='array' THEN json_extract(s.payload, '$.milestones') ELSE '[]' END) item WHERE item.type<>'object'))) OR (p.key='zones' AND (json_type(s.payload, '$.zones')='array' AND json_array_length(CASE WHEN json_type(s.payload, '$.zones')='array' THEN json_extract(s.payload, '$.zones') ELSE '[]' END)<=1000 AND NOT EXISTS(SELECT 1 FROM json_each(CASE WHEN json_type(s.payload, '$.zones')='array' THEN json_extract(s.payload, '$.zones') ELSE '[]' END) item WHERE item.type<>'object'))) OR (p.key='goalMetrics' AND json_type(s.payload, '$.goalMetrics')='object' AND (SELECT json_group_object(entry.key,json(CASE entry.type WHEN 'text' THEN json_quote(entry.value) WHEN 'true' THEN 'true' WHEN 'false' THEN 'false' WHEN 'null' THEN 'null' ELSE entry.value END)) FROM json_each(CASE WHEN json_type(s.payload, '$.goalMetrics')='object' THEN json_extract(s.payload, '$.goalMetrics') ELSE '{}' END) entry WHERE NOT (entry.type IN ('text','true','false','null') OR (entry.type IN ('integer','real') AND abs(entry.value)<=1.7976931348623157e308)))='{}') OR (p.key='appearanceMetrics' AND json_type(s.payload, '$.appearanceMetrics')='object' AND (SELECT json_group_object(entry.key,json(CASE entry.type WHEN 'text' THEN json_quote(entry.value) WHEN 'true' THEN 'true' WHEN 'false' THEN 'false' WHEN 'null' THEN 'null' ELSE entry.value END)) FROM json_each(CASE WHEN json_type(s.payload, '$.appearanceMetrics')='object' THEN json_extract(s.payload, '$.appearanceMetrics') ELSE '{}' END) entry WHERE NOT (entry.type IN ('text','true','false','null') OR (entry.type IN ('integer','real') AND abs(entry.value)<=1.7976931348623157e308)))='{}') OR (p.key='privateMetrics' AND json_type(s.payload, '$.privateMetrics')='object' AND (SELECT json_group_object(entry.key,json(CASE entry.type WHEN 'text' THEN json_quote(entry.value) WHEN 'true' THEN 'true' WHEN 'false' THEN 'false' WHEN 'null' THEN 'null' ELSE entry.value END)) FROM json_each(CASE WHEN json_type(s.payload, '$.privateMetrics')='object' THEN json_extract(s.payload, '$.privateMetrics') ELSE '{}' END) entry WHERE NOT (entry.type IN ('text','true','false','null') OR (entry.type IN ('integer','real') AND abs(entry.value)<=1.7976931348623157e308)))='{}'))),'{}') FROM "_plan_source_PhysiquePlan" s;

INSERT INTO "physique_plan_measurements" (id,parentId,scope,key,valueType,value,stringValue,booleanValue,unit)
SELECT s.id||':goalMetrics:'||hex(j.key),s.id,'goalMetrics',j.key,
 CASE j.type WHEN 'null' THEN 'null' WHEN 'text' THEN 'string' WHEN 'true' THEN 'boolean' WHEN 'false' THEN 'boolean' ELSE 'number' END,
 CASE WHEN j.type IN ('integer','real') THEN CAST(j.value AS REAL) END,
 CASE WHEN j.type='text' THEN j.value END,CASE WHEN j.type IN ('true','false') THEN j.value END,CASE WHEN j.type IN ('integer','real') THEN CASE j.key WHEN 'height' THEN 'cm' WHEN 'weight' THEN 'kg' WHEN 'bodyFat' THEN '%' WHEN 'leanMass' THEN 'kg' WHEN 'skeletalMuscle' THEN 'kg' WHEN 'bodyWater' THEN '%' WHEN 'boneMass' THEN 'kg' WHEN 'visceralFat' THEN 'level' WHEN 'chest' THEN 'cm' WHEN 'waist' THEN 'cm' WHEN 'shoulders' THEN 'cm' WHEN 'shoulderBreadth' THEN 'cm' WHEN 'bideltoidBreadth' THEN 'cm' WHEN 'chestDepth' THEN 'cm' WHEN 'underbust' THEN 'cm' WHEN 'arms' THEN 'cm' WHEN 'forearm' THEN 'cm' WHEN 'wrist' THEN 'cm' WHEN 'elbow' THEN 'cm' WHEN 'neck' THEN 'cm' WHEN 'hips' THEN 'cm' WHEN 'highHip' THEN 'cm' WHEN 'pelvicBreadth' THEN 'cm' WHEN 'glutes' THEN 'cm' WHEN 'thighs' THEN 'cm' WHEN 'calves' THEN 'cm' WHEN 'ankle' THEN 'cm' WHEN 'torsoLength' THEN 'cm' WHEN 'sittingHeight' THEN 'cm' WHEN 'upperArm' THEN 'cm' WHEN 'lowerArm' THEN 'cm' WHEN 'handLength' THEN 'cm' WHEN 'legLength' THEN 'cm' WHEN 'upperLegLength' THEN 'cm' WHEN 'lowerLegLength' THEN 'cm' WHEN 'inseam' THEN 'cm' WHEN 'neckLength' THEN 'cm' WHEN 'footLength' THEN 'cm' WHEN 'headCirc' THEN 'cm' WHEN 'faceWidth' THEN 'cm' WHEN 'faceHeight' THEN 'cm' WHEN 'eyeSpacing' THEN 'cm' WHEN 'earLength' THEN 'cm' WHEN 'earWidth' THEN 'cm' WHEN 'noseLength' THEN 'cm' WHEN 'noseWidth' THEN 'cm' WHEN 'anatomyLengthCm' THEN 'cm' WHEN 'anatomyGirthCm' THEN 'cm' WHEN 'd_size' THEN 'in' WHEN 'd_length' THEN 'in' WHEN 'd_girth' THEN 'in' WHEN 'leftShoulder' THEN 'cm' WHEN 'rightShoulder' THEN 'cm' WHEN 'leftUpperArm' THEN 'cm' WHEN 'rightUpperArm' THEN 'cm' WHEN 'leftForearm' THEN 'cm' WHEN 'rightForearm' THEN 'cm' WHEN 'leftWrist' THEN 'cm' WHEN 'rightWrist' THEN 'cm' WHEN 'leftThigh' THEN 'cm' WHEN 'rightThigh' THEN 'cm' WHEN 'leftCalf' THEN 'cm' WHEN 'rightCalf' THEN 'cm' WHEN 'leftHip' THEN 'cm' WHEN 'rightHip' THEN 'cm' WHEN 'headTiltAngle' THEN 'deg' WHEN 'pelvicTilt' THEN 'deg' WHEN 'shoulderRounding' THEN 'deg' WHEN 'shoulderTilt' THEN 'deg' WHEN 'spineCurvature' THEN 'deg' WHEN 'hipRotation' THEN 'deg' WHEN 'kneeAlignment' THEN 'deg' WHEN 'leftKneeAngle' THEN 'deg' WHEN 'rightKneeAngle' THEN 'deg' WHEN 'leftFootRotation' THEN 'deg' WHEN 'rightFootRotation' THEN 'deg' WHEN 'brow_depth' THEN 'ratio' WHEN 'nose_bridge_width' THEN 'ratio' WHEN 'nose_tip_size' THEN 'ratio' WHEN 'ear_prominence' THEN 'ratio' WHEN 'jaw_width' THEN 'ratio' WHEN 'chin_projection' THEN 'ratio' WHEN 'lip_fullness' THEN 'ratio' WHEN 'eye_size' THEN 'ratio' END END
 FROM "_plan_source_PhysiquePlan" s,json_each(CASE WHEN json_type(s.payload, '$.goalMetrics')='object' THEN json_extract(s.payload, '$.goalMetrics') ELSE '{}' END) j WHERE (j.type IN ('text','true','false','null') OR (j.type IN ('integer','real') AND abs(j.value)<=1.7976931348623157e308));

