 'deg' WHEN 'shoulderTilt' THEN 'deg' WHEN 'spineCurvature' THEN 'deg' WHEN 'hipRotation' THEN 'deg' WHEN 'kneeAlignment' THEN 'deg' WHEN 'leftKneeAngle' THEN 'deg' WHEN 'rightKneeAngle' THEN 'deg' WHEN 'leftFootRotation' THEN 'deg' WHEN 'rightFootRotation' THEN 'deg' WHEN 'brow_depth' THEN 'ratio' WHEN 'nose_bridge_width' THEN 'ratio' WHEN 'nose_tip_size' THEN 'ratio' WHEN 'ear_prominence' THEN 'ratio' WHEN 'jaw_width' THEN 'ratio' WHEN 'chin_projection' THEN 'ratio' WHEN 'lip_fullness' THEN 'ratio' WHEN 'eye_size' THEN 'ratio' END END
