308)) AND json_type(s.payload, '$.current') IN ('integer','real') THEN json_extract(s.payload, '$.current') END,CASE WHEN json_type(s.payload, '$.current')='text' THEN json_extract(s.payload, '$.current') END,CASE WHEN json_type(s.payload, '$.current') IN ('true','false') THEN json_extract(s.payload, '$.current') END,CASE WHEN (json_type(s.payload, '$.target') IN ('text','true','false','null') OR (json_type(s.payload, '$.target') IN ('integer','real') AND abs(json_extract(s.payload, '$.target'))<=1.7976931348623157e308)) THEN CASE json_type(s.payload, '$.target') WHEN 'text' THEN 'string' WHEN 'true' THEN 'boolean' WHEN 'false' THEN 'boolean' WHEN 'null' THEN 'null' ELSE 'number' END END,CASE WHEN (json_type(s.payload, '$.target') IN ('text','true','false','null') OR (json_type(s.payload, '$.target') IN ('integer','real') AND abs(json_extract(s.payload, '$.target'))<=1.7976931348623157e308)) AND json_type(s.payload, '$.target') IN ('integer','real') THEN json_extract(s.payload, '$.target') END,CASE WHEN json_type(s.payload, '$.target')='text' THEN json_extract(s.payload, '$.target') END,CASE WHEN json_type(s.payload, '$.target') IN ('true','false') THEN json_extract(s.payload, '$.target') END,(SELECT json_group_array(p.key) FROM json_each(s.payload) p WHERE (p.key='id' AND (json_type(s.payload, '$.id') IN ('text','null') OR (json_type(s.payload, '$.id') IN ('integer','real') AND abs(json_extract(s.payload, '$.id'))<=1.7976931348623157e308))) OR (p.key='createdAt' AND json_type(s.payload, '$.createdAt') IN ('text','null')) OR (p.key='updatedAt' AND json_type(s.payload, '$.updatedAt') IN ('text','null')) OR (p.key='label' AND json_type(s.payload, '$.label') IN ('text','null')) OR (p.key='metric' AND json_type(s.payload, '$.metric') IN ('text','null')) OR (p.key='key' AND json_type(s.payload, '$.key') IN ('text','null')) OR (p.key='current' AND (json_type(s.payload, '$.current') IN ('text','true','false','null') OR (json_type(s.payload, '$.current') IN ('integer','real') AND abs(json_extract(s.payload, '$.current'))<=1.7976931348623157e308))) OR (p.key='target' AND (json_type(s.payload, '$.target') IN ('text','true','false','null') OR (json_type(s.payload, '$.target') IN ('integer','real') AND abs(json_extract(s.payload, '$.target'))<=1.7976931348623157e308)))),NULLIF((SELECT json_group_object(p.key,json(CASE p.type WHEN 'text' THEN json_quote(p.value) WHEN 'true' THEN 'true' WHEN 'false' THEN 'false' WHEN 'null' THEN 'null' ELSE p.value END)) FROM json_each(s.payload) p WHERE NOT ((p.key='id' AND (json_type(s.payload, '$.id') IN ('text','null') OR (json_type(s.payload, '$.id') IN ('integer','real') AND abs(json_extract(s.payload, '$.id'))<=1.7976931348623157e308))) OR (p.key='createdAt' AND json_type(s.payload, '$.createdAt') IN ('text','null')) OR (p.key='updatedAt' AND json_type(s.payload, '$.updatedAt') IN ('text','null')) OR (p.key='label' AND json_type(s.payload, '$.label') IN ('text','null')) OR (p.key='metric' AND json_type(s.payload, '$.metric') IN ('text','null')) OR (p.key='key' AND json_type(s.payload, '$.key') IN ('text','null')) OR (p.key='current' AND (json_type(s.payload, '$.current') IN ('text','true','false','null') OR (json_type(s.payload, '$.current') IN ('integer','real') AND abs(json_extract(s.payload, '$.current'))<=1.7976931348623157e308))) OR (p.key='target' AND (json_type(s.payload, '$.target') IN ('text','true','false','null') OR (json_type(s.payload, '$.target') IN ('integer','real') AND abs(json_extract(s.payload, '$.target'))<=1.7976931348623157e308))))),'{}') FROM "_plan_source_PhysiqueTarget" s;

